    "project/contracts/accountLayer/storages/AccountStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

/// @notice Isolation type for virtual accounts determining how positions are grouped
enum VirtualAccountIsolationType {
	POSITION,
	MARKET,
	MARKET_LONG,
	MARKET_SHORT
}

/// @notice Isolation type for sub-accounts determining the VA creation strategy
enum SubAccountIsolationType {
	POSITION,
	MARKET,
	MARKET_DIRECTION,
	CUSTOM
}

/// @notice Persistent configuration data for a sub-account
struct SubAccountData {
	string name;
	address owner;
	bool isExists;
	bool singleVAMode;
	bytes metadata;
	address affiliate;
	address symmioCore;
	SubAccountIsolationType isolationType;
}

/// @notice Persistent configuration data for a virtual account
struct VirtualAccountData {
	bool isExists;
	bytes metadata;
	address parentAccount;
	uint256 symbolId;
	VirtualAccountIsolationType isolationType;
	EnumerableSet.UintSet quoteIds;
}

/// @notice Input parameters for creating a new sub-account
struct SubAccountCreationData {
	string name;
	bytes metadata;
	address symmioCore;
	SubAccountIsolationType isolationType;
	bool singleVAMode;
}

/// @notice View-layer representation of a sub-account with its address included
struct SubAccountDetail {
	address accountAddress;
	address owner;
	string name;
	bool isExists;
	bool singleVAMode;
	address affiliate;
	address symmioCore;
	bytes metadata;
	SubAccountIsolationType isolationType;
}

/// @notice View-layer representation of a virtual account with its address included
struct VirtualAccountDetail {
	address accountAddress;
	address parentAccount;
	uint256 symbolId;
	bool isExists;
	bytes metadata;
	VirtualAccountIsolationType isolationType;
}

/// @notice Information about a legacy MultiAccount-based account
struct LegacyAccountInfo {
	address accountAddress;
	string name;
	address legacyContract;
	bool alreadyImported;
}

/// @notice Input parameters for importing a legacy account into the new system
struct LegacyAccountImportData {
	address account;
	string name;
	uint256 coreIndex;
}

/// @title AccountStorage
/// @notice Unified account management with SubAccounts and Virtual Accounts (VAs)
/// @dev Replaces per-affiliate MultiAccount deployments with a single hub. Creates a
///      three-tier hierarchy: User → SubAccounts → Virtual Accounts. SubAccounts define
///      isolation strategy, VAs are the actual trading addresses interacting with Symmio.
library AccountStorage {
	bytes32 internal constant ACCOUNT_STORAGE_SLOT = keccak256("diamond.standard.storage.accountlayer.account");

	struct Layout {
		/// @notice SubAccount configuration by address
		/// @dev SubAccount addresses are deterministic via CREATE2. Contains owner,
		///      affiliate, symmioCore, and isolation type (POSITION/MARKET/MARKET_DIRECTION/CUSTOM).
		mapping(address => SubAccountData) subAccounts;
		/// @notice SubAccounts owned by each user
		/// @dev Maps user => set of their SubAccount addresses. A user can have multiple
		///      SubAccounts for different affiliates, cores, or isolation strategies.
		mapping(address => EnumerableSet.AddressSet) userToSubAccounts;
		/// @notice Virtual Account configuration by address
		/// @dev VA addresses are deterministic. Contains parent SubAccount, symbolId,
		///      isolation type, and tracked quoteIds for lifecycle management.
		mapping(address => VirtualAccountData) virtualAccounts;
		/// @notice Virtual Accounts under each SubAccount
		/// @dev Maps SubAccount => set of its VA addresses. Used for iteration and cleanup.
		mapping(address => EnumerableSet.AddressSet) subAccountToVirtualAccounts;
		/// @notice Pool of inactive VAs available for reuse
		/// @dev When VAs are deactivated (all positions closed), they're pooled here
		///      instead of discarded. Maps parent => isolationType => symbolId => addresses.
		///      Reusing addresses avoids unbounded address growth over time.
		mapping(address => mapping(VirtualAccountIsolationType => mapping(uint256 => address[]))) deletedVirtualAccountsPool;
		/// @notice Currently active VA per isolation key (used in singleVAMode)
		/// @dev Maps subAccount => isolationType => symbolId => active VA. In singleVAMode,
		///      only one VA can be active per key, simplifying frontend address management.
		mapping(address => mapping(VirtualAccountIsolationType => mapping(uint256 => address))) activeVAByKey;
		/// @notice Global counter for SubAccount address generation
		/// @dev Part of CREATE2 salt. Incremented on each SubAccount creation.
		uint256 globalNonce;
		/// @notice Per-SubAccount counter for VA address generation
		/// @dev Maps SubAccount => nonce. Next VA address = _generateVirtualAccountAddress(parent, nonce).
		mapping(address => uint256) subAccountVirtualNonces;
		/// @notice Authorized signer for protocol-level operations
		/// @dev Used for operations requiring protocol authorization.
		address globalSigner;
		/// @notice Bytecode for AccountManager deployment
		/// @dev AccountManagers are full contracts deployed per affiliate via CREATE2.
		bytes accountManagerImplementation;
		/// @notice Expected code hash after AccountManager initialization
		/// @dev Used to verify AccountManagers deployed correctly.
		bytes32 initAccountManagerCodeHash;
		/// @notice PartyBs that closed positions with a VA while in cross liquidation.
		/// @dev Maps VA address => set of partyBs with pending cross liq distributions.
		/// Used to defer VA deletion until distributeForClearingHouse has credited the VA's share,
		/// even when the final hook fires with a different partyB.
		mapping(address => EnumerableSet.AddressSet) vaPendingCrossLiqPartyBs;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = ACCOUNT_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/accountLayer/storages/AffiliateStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

import { EnumerableSet } from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

/// @notice Lifecycle state of an affiliate registration
enum AffiliateState {
	NONE,
	PENDING,
	ACTIVE,
	PAUSED
}

/// @notice A fee recipient with their share of the affiliate's fee split
struct Stakeholder {
	address receiver;
	uint256 share;
}

/// @notice Fee distribution configuration for an affiliate
struct FeeDetails {
	uint256 symmioShare;
	Stakeholder[] stakeholders;
	address feeDistributor;
}

/// @notice Full configuration and state for a registered affiliate
struct AffiliateData {
	string name;
	string brandColor;
	address admin;
	address pendingAdmin;
	AffiliateState state;
	FeeDetails feeDetails;
	bytes metadata;
	address[] legacyMultiAccounts;
	EnumerableSet.AddressSet symmioCores;
	mapping(bytes4 => address) hooks;
	address accountManager;
	address registrant;
	uint256 expressRate;
	address virtualProvider;
	uint256 registrationNonce;
}

/// @notice Input parameters for registering a new affiliate
struct AffiliateRegistration {
	string name;
	string brandColor;
	address admin;
	Stakeholder[] stakeholders;
	uint256 symmioShare;
	bytes metadata;
	address[] legacyMultiAccounts;
	address[] symmioCores;
}

/// @notice A pending fee configuration change awaiting approval
struct PendingFeeUpdate {
	bool exists;
	uint256 timestamp;
	uint256 symmioShare;
	Stakeholder[] stakeholders;
}

/// @notice Contextual information available to hooks during execution
struct HookContext {
	address account;
	address affiliate;
	address symmioCore;
	bool isActive;
	address activeHook;
}

/// @title AffiliateStorage
/// @notice Affiliate registration, fee splits, and hook management
/// @dev Replaces per-frontend MultiAccount deployments. Affiliates register via
///      requestToRegisterAffiliate (PENDING) and are activated by APPROVER_ROLE.
///      Fees accrue in a deterministic feeDistributor address and are split on-chain
///      between stakeholders and Symmio (shares must sum to 1e18).
library AffiliateStorage {
	bytes32 internal constant AFFILIATE_STORAGE_SLOT = keccak256("diamond.standard.storage.accountlayer.affiliate");

	struct Layout {
		/// @notice All registered affiliate configurations
		/// @dev Maps affiliate address (= AccountManager address) => full config.
		///      Affiliate address is deterministic: generateAccountManagerAddress(registrant, name, nonce).
		mapping(address => AffiliateData) affiliates;
		/// @notice Pending fee configuration changes awaiting approval
		/// @dev Fee updates are two-step: requestFeeUpdate (admin) → approveFeeUpdate (APPROVER_ROLE).
		///      Timestamp recorded for audit trail, no enforced delay.
		mapping(address => PendingFeeUpdate) pendingFeeUpdates;
		/// @notice Operator permissions per affiliate per function
		/// @dev Affiliates can authorize operators for specific functions via setOperator.
		///      Maps affiliate => selector => operator => allowed.
		mapping(address => mapping(bytes4 => mapping(address => bool))) operators;
		/// @notice Set of all legacy MultiAccount contracts
		/// @dev For backward compatibility. AccountLayer.ownerOf() scans these for ownership.
		EnumerableSet.AddressSet legacyMultiAccounts;
		/// @notice Whitelisted Symmio core contracts
		/// @dev Affiliates can only operate on whitelisted cores. Prevents connection
		///      to unauthorized diamonds. Managed by SETTER_ROLE.
		mapping(address => bool) whitelistedSymmioCores;
		/// @notice Protocol address receiving Symmio's share of fees
		/// @dev When claimFees is called, symmioShare portion goes here.
		address symmioFeeReceiver;
		/// @notice Counter for deterministic fee distributor address generation
		/// @dev Each affiliate gets a unique fee distributor address via CREATE2.
		uint256 globalNonce;
		/// @notice Current context during hook execution
		/// @dev Set when entering a hook, cleared on exit. Hooks can read this to
		///      know which account/affiliate/core triggered them.
		HookContext hookContext;
		/// @notice Which selectors can trigger hooks per affiliate
		/// @dev Maps affiliate => selector => allowed. Hooks are external calls that
		///      can execute custom logic (mint NFT, issue cashback, etc.).
		mapping(address => mapping(bytes4 => bool)) hookAllowedSelectors;
		/// @notice Which selectors affiliates can call via callAsAffiliate
		/// @dev Maps affiliate => selector => allowed. callAsAffiliate executes with
		///      setSigner(affiliate) on the target Symmio core.
		mapping(address => mapping(bytes4 => bool)) callAllowedSelectors;
		/// @notice Monotonic nonce per registrant for affiliate address generation
		/// @dev Ensures every request gets a unique affiliate address, even with the same name/registrant pair.
		mapping(address => uint256) registrationNonces;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = AFFILIATE_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
